function debounce(fn, ms) {
  let t;
  return (...a) => {
    clearTimeout(t);              // сбрасываем прошлый таймер
    t = setTimeout(() => fn(...a), ms);
  };
}
function throttle(fn, ms) {
  let last = 0;
  return (...a) => {
    if (Date.now() - last >= ms) { // прошло ли N мс?
      last = Date.now();
      fn(...a);
    }
  };
}

